using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable] public class R16IntegrationRow {public string id,launch,final,afterOverview;public bool resultSnapshotTruth,pauseStable,overviewBodyStable,retryClean;public float startSize,endSize;public List<BreakRecord> actualBreaks=new List<BreakRecord>();}
 [Serializable] public class R16IntegrationReport {public string state="RUNNING",method="Combined module Native input-equivalent 601charge ticks, standard12/power100/work2, one normal and one reduced; no human play or audio listening. Compare same-version normal/reduced separately from saved pre-integration metrics.";public List<R16IntegrationRow> rows=new List<R16IntegrationRow>();}
 [UnityTest] public IEnumerator R16Integration(){Directory.CreateDirectory(Evidence);string file=Path.Combine(Evidence,"integration.json");Assert.That(File.Exists(file),Is.False);var report=new R16IntegrationReport();Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();
 foreach(bool reduced in Environment.GetEnvironmentVariable("CRAB_EVIDENCE_SCOPE")=="integrate02"?new[]{false}:new[]{false,true}){yield return NewRetrySubject(reduced,true,true,true,true,true,true);StartRouteChargeR11(12,0,2,1);var row=new R16IntegrationRow{id=reduced?"reduced":"normal",launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.rows.Add(row);var sim=Property(current,"ReviewSimulation");int capture=0;
 for(int i=0;i<11000&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);float d=F(State(current),"distance");if(capture<3&&d>new[]{6f,100f,650f}[capture]){CaptureRoute(row.id,"flight"+capture);capture++;}}
 row.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);
 var overview=Field(State(current),"resultOverview");row.resultSnapshotTruth=overview!=null&&Convert.ToInt32(Field(overview,"broken"))==row.actualBreaks.Count;var points=(float[])Field(overview,"breaks");for(int k=0;k<points.Length;k++)row.resultSnapshotTruth&=points[k]==row.actualBreaks[k].position.x;Assert.That(row.resultSnapshotTruth,Is.True);
 var camera=(Camera)Property(current,"ReviewCamera");var position=camera.transform.position;row.startSize=camera.orthographicSize;string body=(string)Call(sim,"LaunchBodyReceipt");float time=F(State(current),"time");Call(current,"SetPaused","1");Call(current,"Tick",.5f);row.pauseStable=camera.transform.position==position&&camera.orthographicSize==row.startSize&&F(State(current),"time")==time;Call(current,"SetPaused","0");for(int i=0;i<90;i++)Call(current,"Tick",1f/60);row.endSize=camera.orthographicSize;row.overviewBodyStable=body==(string)Call(sim,"LaunchBodyReceipt")&&F(State(current),"time")==time;Assert.That(row.pauseStable&&row.overviewBodyStable,Is.True);if(reduced)Assert.That(camera.transform.position==position&&row.startSize==row.endSize,Is.True);else Assert.That(row.endSize,Is.GreaterThanOrEqualTo(row.startSize));row.afterOverview=JsonUtility.ToJson(State(current));CaptureRoute(row.id,"overview");
 Call(current,"RetryLaunch","");var st=State(current);row.retryClean=(string)Field(st,"phase")=="flight"&&Field(st,"resultOverview")==null&&F(st,"hitStopRemaining")==0&&Convert.ToInt32(Field(st,"destructionEvent"))==0;Assert.That(row.retryClean,Is.True);Call(current,"Prepare","");Assert.That(F(State(current),"time"),Is.EqualTo(0));Assert.That(F(State(current),"chargeWork"),Is.EqualTo(0));save();Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}
}
